-- pay_waffo_abort_before_dispatch(uuid,uuid,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_waffo_abort_before_dispatch(p_user uuid, p_order uuid, p_merchant text, p_expected timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE o payment_orders;
BEGIN
 PERFORM pay_waffo_assert_actor(p_user);
 SELECT * INTO o FROM payment_orders WHERE id=p_order AND user_id=p_user FOR UPDATE;
 IF o.id IS NULL OR NOT pay_method_mode_allowed(o.payment_channel,o.payment_mode) OR NOT (o.payment_channel='stripe' OR o.payment_channel='waffo' AND o.mode='payment'
    AND NOT o.auto_renew AND o.method_dispatched_at IS NULL)
  OR o.merchant_namespace IS DISTINCT FROM p_merchant OR o.payment_method NOT IN ('alipay','wechat_pay','card','card_cn')
  -- A never-claimed order (no request frozen, nothing sent to Stripe) is released with p_expected NULL;
  -- a claimed one only with its exact frozen expiry. The claim refuses released or closed orders.
  OR (o.method_dispatched_at IS NULL) IS DISTINCT FROM (p_expected IS NULL)
  OR (o.method_dispatched_at IS NOT NULL AND o.method_checkout_expires_at IS DISTINCT FROM p_expected)
  OR o.payment_status IS DISTINCT FROM 'unpaid' OR o.fulfilled_at IS NOT NULL
  OR EXISTS(SELECT 1 FROM payment_provider_refs WHERE order_id=o.id AND object_type IN ('checkout','payment')) THEN
  RAISE EXCEPTION 'PAY_WAFFO_CLOSE_DENIED'; END IF;
 IF o.qualification_state='released' AND o.qualification_closed_ref='never_dispatched:'||o.id THEN RETURN; END IF;
 IF o.qualification_state IS DISTINCT FROM 'reserved' THEN RAISE EXCEPTION 'PAY_WAFFO_CLOSE_DENIED'; END IF;
 UPDATE payment_orders SET qualification_state='released',qualification_closed_ref='never_dispatched:'||o.id,
  purchase_closed_at=clock_timestamp(),method_review_reason='checkout_not_dispatched' WHERE id=o.id;
END $function$;
